const keyword = 'CAMBIA_ESTE_TEXTO';

return $input.all()
  .filter((item) => {
    const subject = String(item.json.subject ?? '');
    return subject.toLowerCase().includes(keyword.toLowerCase());
  })
  .map((item) => {
    const fromText = item.json.from?.text ?? item.json.from?.value?.[0]?.address ?? 'desconocido';
    const subject = item.json.subject ?? '(sin asunto)';
    const receivedDate = item.json.date ?? new Date().toISOString();
    const plainText = String(item.json.textPlain ?? item.json.textHtml ?? '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 500);

    item.json.whatsAppText = [
      'Correo detectado por n8n',
      `Asunto: ${subject}`,
      `De: ${fromText}`,
      `Fecha: ${receivedDate}`,
      plainText ? `Resumen: ${plainText}` : 'Resumen: (sin contenido legible)'
    ].join('\n');

    return item;
  });
